export function ShortcutHelp({ onClose }: ShortcutHelpProps) {
  const modalRef = useRef<HTMLDivElement>(null);

  // Use shared focus trap hook
  useModalFocusTrap(modalRef, onClose, { autoFocus: true, onEscape: true });

  return (
    <div
      ref={modalRef}
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="shortcut-help-title"
      onClick={(e) => {
        // Close on background click
        if (e.target === e.currentTarget) {
          onClose();
        }
      }}>
      <div className="bg-card border shadow-lg rounded-lg max-w-2xl w-full max-h-[80vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b">
          <h3 id="shortcut-help-title" className="text-lg font-semibold flex items-center gap-2">
            <span aria-hidden="true">⌨️</span>
            <span>快捷键列表</span>
          </h3>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-foreground p-1 rounded hover:bg-accent transition-colors"
            aria-label="关闭对话框"
            autoFocus
          >
            ✕
          </button>
        </div>

        {/* Shortcuts list */}
        <div className="flex-1 overflow-y-auto p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {SHORTCUT_GROUPS.map((group) => (
              <div key={group.category} className="space-y-2">
                <div className="text-sm font-medium text-muted-foreground flex items-center gap-2">
                  <span className="w-1 h-4 bg-primary rounded-full" />
                  {group.category}
                </div>
                <div className="space-y-1">
                  {group.shortcuts.map(({ key, description }, idx) => (
                    <div
                      key={`${key}-${idx}`}
                      className="flex items-center justify-between py-1 px-2 rounded hover:bg-accent/30 transition-colors text-xs"
                    >
                      <kbd className="px-2 py-1 bg-muted rounded font-mono border">
                        {key}
                      </kbd>
                      <span className="text-muted-foreground">{description}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-muted/30">
          <div className="flex gap-2 text-xs text-muted-foreground">
            <span>总计: {SHORTCUT_GROUPS.reduce((sum, g) => sum + g.shortcuts.length, 0)} 个快捷键</span>
            <span className="ml-auto">按 Esc 或点击关闭</span>
          </div>
          <button
            onClick={onClose}
            className="w-full mt-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg text-sm hover:bg-primary/90 transition-colors"
          >
            关闭
          </button>
        </div>
      </div>
    </div>
  );
}